{"source":"def investigate(context, acquire):
    def is_cont(b):
        return 128 <= b <= 191

    def decode_chunk(state, data, final):
        out = []
        i = 0
        n = len(data)
        while i < n:
            b = data[i]
            if state['pending']:
                if is_cont(b):
                    state['pending'].append(b)
                    i += 1
                    if len(state['pending']) == state['need']:
                        out.append(chr(int.from_bytes(state['pending'], 'big')))
                        state['pending'] = None
                        state['need'] = 0
                    continue
                state['pending'] = None
                state['need'] = 0
                return None
            if b < 128:
                out.append(chr(b))
                i += 1
            elif 192 <= b <= 223:
                state['pending'] = [b]
                state['need'] = 2
                i += 1
            elif 224 <= b <= 239:
                state['pending'] = [b]
                state['need'] = 3
                i += 1
            elif 240 <= b <= 247:
                state['pending'] = [b]
                state['need'] = 4
                i += 1
            else:
                return None
        if final:
            if state['pending']:
                state['pending'] = None
                state['need'] = 0
                return None
        return ''.join(out)

    events = context['events']
    state = {'pending': None, 'need': 0}
    count = 0
    status = 'open'
    for ev in events:
        op = ev['op']
        if op == 'feed':
            result = decode_chunk(state, ev['bytes'], False)
            if result is None:
                status = 'error'
            else:
                count += len(result)
        elif op == 'finish':
            result = decode_chunk(state, [], True)
            if result is None:
                status = 'error'
            else:
                count += len(result)
                status = 'finished'
        elif op == 'reset':
            state = {'pending': None, 'need': 0}
            count = 0
            status = 'open'
    return {'count': count, 'status': status}
